function recruitmentSites(s,country){return s.sites.filter(p=>s.territories[p.territory].settlementLevel>0&&s.territories[p.territory].owner===country&&!living(s).some(u=>u.territory===p.territory&&!ally(s,u.country,country)));}
function create(world){const {cells,territories}=group(world);const s={schema:'council-regiments-v1',turn:1,phase:'orders',countries:world.countries.map(c=>({id:c.id,name:c.name,color:c.color,shield:'',stock:{money:100,food:120,wood:50,metal:40},movement:2,research:false,capital:null})),cells,territories,units:[],nextId:1,alliances:[],offers:[],choices:{},ready:[],conflicts:[],moves:[],battles:[],history:[],captureChoices:{}};
 s.countries.forEach(c=>{const own=territories.filter(t=>t.home===c.id);if(!own.length)return;const cap=own.sort((a,b)=>Math.hypot(a.point[0]-world.countries[c.id].capital[0],a.point[1]-world.countries[c.id].capital[1])-Math.hypot(b.point[0]-world.countries[c.id].capital[0],b.point[1]-world.countries[c.id].capital[1]))[0];cap.owner=c.id;c.capital=cap.id;['spears','archers'].forEach(type=>s.units.push({id:s.nextId++,country:c.id,type,hp:100,territory:cap.id,order:null,fatigue:0,retreat:null,retreatTo:null}));});return upgradeCaptureAgreements(upgradeSettlements(upgradeWellbeing(upgradeEconomy(s,world.settlements||[]))));}
function phase(s,p){fail(s.phase===p,`This action belongs to the ${p} phase.`);}
function pay(stock,cost){fail(goods.every(g=>stock[g]>=(cost[g]||0)),'Not enough delivered resources in this department. Economy allocations arrive after the full round.');goods.forEach(g=>stock[g]-=cost[g]||0);}
function recruit(s,country,type,territory){phase(s,'orders');fail(Object.hasOwn(types,type),'Choose a regiment type.');fail(recruitmentSites(s,country).some(p=>p.territory===territory),'Recruit at a controlled village, town or city without hostile troops.');fail(!living(s).some(u=>u.territory===territory&&!ally(s,u.country,country)),'Cannot recruit beside a hostile force.');fail(living(s).filter(u=>u.country===country).length<6,'Six regiments maximum per country.');pay(s.countries[country].accounts.military,{money:50,food:4,wood:type==='archers'?20:5,metal:type==='archers'?5:20});s.units.push({id:s.nextId++,country,type,hp:100,territory,order:null,fatigue:0,retreat:null,retreatTo:null,readyTurn:s.turn+1});}
function research(s,country){phase(s,'orders');const c=s.countries[country];fail(c.movement<4&&!c.research,'Movement research is complete or already funded.');pay(c.accounts.research,{money:60,wood:15,metal:15});c.research=true;}
function route(s,from,to,country){if(from===to)return [];const queue=[from],prev=new Map([[from,null]]);for(let i=0;i<queue.length;i++){const current=queue[i];if(current!==from&&living(s).some(u=>u.territory===current&&!ally(s,u.country,country)))continue;for(const n of s.territories[current].neighbors){if(prev.has(n))continue;prev.set(n,current);if(n===to){const result=[];let k=to;while(k!==from){result.unshift(k);k=prev.get(k);}return result;}queue.push(n);}}return null;}
